@source "./";

/* Tailwind theme: color tokens (so bg-primary/text-foreground resolve to our vars) +
   breakpoints. @theme inline keeps the var() reference (theme-swappable at runtime). */
@theme inline {
  --breakpoint-vp375: 375px;
  --breakpoint-vp768: 768px;
  --breakpoint-vp1280: 1280px;
  --breakpoint-vp1920: 1920px;
  --breakpoint-md: 572px;
  --breakpoint-lg: 1025px;
  --breakpoint-2xl: 1601px;
  --color-foreground: var(--foreground);
  --color-border: var(--border);
  --color-background: var(--background);
  --color-muted-foreground: var(--muted-foreground);
  --color-clr-0: var(--clr-0);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-color-002: var(--color-002);
  --color-muted: var(--muted);
  --color-clr-1: var(--clr-1);
  --color-clr-2: var(--clr-2);
  --color-color-001: var(--color-001);
  --color-accent: var(--accent);
  --color-clr-3: var(--clr-3);
  --color-clr-4: var(--clr-4);
