  --color-clr-11: var(--clr-11);
  --color-clr-12: var(--clr-12);
  --color-clr-13: var(--clr-13);
}

/* Design tokens (values). */
:root {
  --background: rgb(255, 255, 255);
  --foreground: rgb(0, 0, 0);
  --primary: rgb(6, 13, 170);
  --accent: rgb(166, 10, 61);
  --border: rgb(25, 24, 23);
  --muted-foreground: rgb(85, 85, 85);
  --surface: rgb(229, 229, 229);
  --surface-2: rgb(250, 250, 250);
  --muted: rgb(172, 166, 159);
  --color-001: rgb(252, 250, 238);
  --color-002: rgb(116, 116, 116);
}

:root {
  /* fonts */
  --font-body: BeoSupreme, "Lexend Deca", Arial, Helvetica, sans-serif;
  --font-001: "object-fit: cover; object-position: center;";
  /* fontSizes */
